"""Preassign 50 fictional pilot blueprints before model rendering. No training/test promotion."""
import json
from pathlib import Path

# Distinct situations, not name-swapped copies. Related roots will still be flagged by content audit.
PLOTS = [
('A former Army test lead joins a radar subcontractor; explain a direct contribution to acceptance throughput with a fully explained operational benefit.', 'A Navy avionics specialist now maintains depot test stations; state current role and qualifications plainly without a career-change motivation.'),
('An Air Force network veteran withholds client/project names while discussing a public employer and desired technical role; absent facts must remain unknown.', 'A Coast Guard maintenance instructor gives current work and contacts but does not mention any degree or clearance; do not infer credentials from service.'),
('A Marine Corps logistics planner corrects an old work email and replaces an outdated notice period later in the conversation.', 'An Army software engineer retracts a mistakenly stated current title after explaining a promotion; the corrected title replaces the earlier one.'),
('A Navy sensor analyst discusses an old shipboard program and a later civilian data role whose current program is unnamed.', 'An Air Force quality technician describes a previous aircraft effort, then a current ground-equipment role using different tools.'),
('A Coast Guard project coordinator first permits one relocation destination, then refuses relocation but permits periodic travel.', 'A Marine Corps cyber specialist is willing to relocate only after a spouse finishes a school term; preserve the location and timing condition.'),
('An Army test engineer separates annual base, percent bonus, a small monthly allowance and a lower target base chosen for work-life balance.', 'A Navy maintenance specialist contrasts current hourly pay with a prospective annual salaried position; currency and frequency cannot be mixed.'),
('An Air Force program coordinator distinguishes personal reports, matrix contributors and a partner vendor manager mentioned by the interviewer.', 'A Marine Corps analyst describes a teammate’s successful tool migration separately from the candidate’s own reporting contribution.'),
('A Coast Guard veteran holds an expired clearance and a pending application for a different level; neither is a currently held clearance.', 'An Army intelligence veteran uses an ambiguous acronym that the interviewer misinterprets, then explicitly clarifies its meaning.'),
('A Navy software engineer corrects a negated willingness statement across a long complete answer that will later be split into manual chunks.', 'An Air Force training specialist finishes an answer with the actual result only after describing several unsuccessful attempts; fragments must not be labeled early.'),
('A Marine Corps captain explains civilian analyst interests; military rank is not a degree, current civilian title, employer or proof of clearance.', 'A Coast Guard quality engineer names a product/program, employer and software tool in the same answer; assign each to the proper frozen field.'),
('An Army systems engineer identifies how a changed tracking gate affected operator workload and a stated compute-cost trade-off.', 'An Air Force simulator engineer runs many scenarios but does not report the analytical finding; ask what was learned without presuming an improvement.'),
('A Navy maintenance planner discusses parts constraints and a personally owned repair scheduling change with a vague reliability benefit.', 'A Marine Corps training coordinator explains an experiment with clearer instructions, describing a concrete qualitative benefit rather than a percentage.'),
('An Army cyber veteran describes a group-level deployment result with unclear personal contribution despite a numerical outcome.', 'A Coast Guard analyst discusses an interviewer-asserted achievement, denies ownership and states a different actual contribution.'),
('An Air Force avionics veteran explains why a faster test did not benefit the team until a second constraint was removed.', 'A Navy project coordinator describes an accepted schedule-versus-cost trade-off already explained clearly; do not ask for it again.'),
('A Marine Corps logistics veteran explains an older civilian role then a current contract; a role-specific contribution question may be useful without a vague achievement.', 'An Army analyst discusses promotion and what kinds of analysis they preferred; distinguish past interests from a future career preference.'),
('A Coast Guard operations veteran discusses contact corrections and salary only at the cutoff, with no timely work question.', 'An Air Force quality engineer gives notice-period and relocation logistics after a fully explained accomplishment; administrative details should not cause a new question.'),
('A Navy systems veteran resolves an earlier vague impact claim in a later answer, with personal contribution and team value stated explicitly.', 'A Marine Corps software veteran’s most recent answer answers the exact clarification the interviewer was considering; prefer abstention to a stale prompt.'),
('An Army test veteran still has an unquantified work claim, but an equivalent question is already in the recent suggestion history.', 'A Coast Guard maintenance veteran has a useful role question that was already suggested; do not emit a paraphrase of that suggestion.'),
('An Air Force analyst gives a bachelor degree/year and a different master degree/year while distinguishing a colleague’s unrelated credential.', 'A Navy cyber veteran explicitly declines to state service dates and says nothing about a degree; respect both missing values and withholding.'),
('A Marine Corps engineer names two successive employers with similar names and changes current program without changing current employer.', 'An Army project veteran moves from active service to an internship and then a full-time civilian role; anchor tenure to the correct current position.'),
('A Coast Guard software veteran discusses automation scale without a claimed before/after improvement; explore the result rather than invent savings.', 'An Air Force avionics veteran’s quantified improvement may hide a meaningful safety-versus-throughput trade-off that has not been described.'),
('A Navy logistics veteran gives a desired job domain and an explicit funding-related reason for leaving; pay is not the reason for leaving.', 'A Marine Corps quality veteran prefers a different technical discipline while describing satisfaction with the current employer; do not invent dissatisfaction.'),
('An Army training veteran contrasts formal direct reports with temporary exercise participants; do not count every participant as team size.', 'A Coast Guard intelligence veteran discusses multilingual work without claiming proficiency levels or formal certifications; extract only named facts.'),
('An Air Force systems veteran reports a current salary correction from a rounded figure to an exact annual base with a separately stated bonus.', 'A Navy maintenance veteran changes an availability estimate and corrects which employer was current when an earlier achievement occurred.'),
('A Marine Corps software veteran contributes a small component to a larger platform; probe the candidate’s component instead of giving them team-wide credit.', 'An Army quality veteran explains the significance of fewer false alarms using technician time and a stated unchanged missed-defect rate.'),
]
ROLES=['systems_engineering','software_cyber','maintenance_avionics','logistics_operations','program_project_management','technical_training','intelligence_analysis','quality_test']
RISKS=['direct_facts','missing_information','corrections_and_retractions','current_vs_historical','negation_and_conditions','numbers_units_and_ranges','multiple_entities_and_speakers','evidence_and_ambiguity','response_continues_across_chunks','frozen_field_assignment']
QUESTIONS=['ask_quantify_impact']*6+['ask_clarify_ownership']*4+['ask_clarify_claim']*4+['ask_clarify_value_or_tradeoff']*6+['ask_explore_role_or_interest']*5+['abstain_already_complete']*8+['abstain_contact_or_logistics']*7+['abstain_answered_in_context']*5+['abstain_previously_suggested']*5
MODELS=['anthropic/claude-haiku-4.5','google/gemini-3.5-flash-lite']
DENSITY=['sparse']*18+['medium']*20+['dense']*12
DIFFICULTY=['easy']*15+['medium']*20+['hard']*15
# Coprime permutations avoid assigning one model/role all the hard or dense roots.
RISK_ASSIGNMENTS=[risk for risk in RISKS for _ in range(2)]+['direct_facts', 'direct_facts', 'missing_information', 'missing_information', 'multiple_entities_and_speakers', 'multiple_entities_and_speakers', 'current_vs_historical', 'negation_and_conditions', 'frozen_field_assignment', 'frozen_field_assignment', 'numbers_units_and_ranges', 'numbers_units_and_ranges', 'multiple_entities_and_speakers', 'evidence_and_ambiguity', 'evidence_and_ambiguity', 'evidence_and_ambiguity', 'response_continues_across_chunks', 'response_continues_across_chunks', 'current_vs_historical', 'frozen_field_assignment', 'direct_facts', 'negation_and_conditions', 'missing_information', 'negation_and_conditions', 'corrections_and_retractions', 'corrections_and_retractions', 'numbers_units_and_ranges', 'corrections_and_retractions', 'response_continues_across_chunks', 'current_vs_historical']
ROLE_ASSIGNMENTS=['quality_test', 'maintenance_avionics', 'software_cyber', 'technical_training', 'logistics_operations', 'software_cyber', 'intelligence_analysis', 'quality_test', 'program_project_management', 'software_cyber', 'quality_test', 'maintenance_avionics', 'program_project_management', 'intelligence_analysis', 'program_project_management', 'intelligence_analysis', 'software_cyber', 'technical_training', 'intelligence_analysis', 'quality_test', 'systems_engineering', 'systems_engineering', 'logistics_operations', 'technical_training', 'software_cyber', 'intelligence_analysis', 'maintenance_avionics', 'program_project_management', 'logistics_operations', 'intelligence_analysis', 'logistics_operations', 'quality_test', 'systems_engineering', 'software_cyber', 'quality_test', 'maintenance_avionics', 'intelligence_analysis', 'software_cyber', 'systems_engineering', 'program_project_management', 'software_cyber', 'maintenance_avionics', 'logistics_operations', 'quality_test', 'technical_training', 'intelligence_analysis', 'systems_engineering', 'maintenance_avionics', 'software_cyber', 'quality_test']
rows=[]
for index,plot in enumerate([item for pair in PLOTS for item in pair]):
    template=index//2
    rows.append({'root_id':f'pilot-{index+1:03}', 'scenario_group_id':f'pilot-scenario-{index+1:03}', 'template_family':f'pilot-pattern-{template+1:02}', 'split':'pilot_review_only',
      'generator_model':MODELS[index%2], 'reviewer_model':MODELS[1-index%2], 'domain_scope':'us_veteran_civilian_job_interviews_v1',
      'role_family':ROLE_ASSIGNMENTS[index], 'primary_risk':RISK_ASSIGNMENTS[index], 'question_outcome_intent':QUESTIONS[(index*17)%50],
      'density_intent':DENSITY[(index*13)%50], 'difficulty_intent':DIFFICULTY[(index*19)%50], 'plot':plot,
      'privacy':'Entirely fictional. No real candidate transcript or customer data.'})
assert len(rows)==50
# Opposite parity risk assignment otherwise confounds model and risk: alternate every group of ten.
for index,row in enumerate(rows):
    model_index=(index+(index//10))%2; row['generator_model']=MODELS[model_index];row['reviewer_model']=MODELS[1-model_index]
Path(__file__).with_name('plan.json').write_text(json.dumps({'version':'pilot-v1','status':'planned_not_generated','released_for_training':False,'released_for_evaluation':False,'roots':rows},indent=2)+'\n')
print('Planned 50 roots, 25 per model, 25 template families and 8 roles. Intent tags are generation targets, not validated labels.')
